template <class T>
class AvlTree;

template <class T>
class TreeNode
{
protected:
	friend class AvlTree<T>;

	TreeNode *l;
	TreeNode *r;
	TreeNode *p;

	T *d;
	char h;
};

template <class T>
class AvlTree
{
protected:
	typedef TreeNode<T> TNode;

	TNode *rootNode;

	int s;

	char disposeElements;

	void dump(TNode * &node, int delData)
	//void dump(TreeNode * &node, int delData)
  {
  	if(node != NULL)
  	{
  		dump(node->l, delData);
  		dump(node->r, delData);

  		if(delData && node->d != NULL)
  			delete node->d;

  		delete node;
  		node = NULL;

  		s--;
  	}
  }
};

template void AvlTree<path_info_node>::dump(TreeNode<path_info_node>* &, int);
